export function renderDriverAuth(api,page,step=1){
 const {root,profile,field,select,icon,box,logo,link,notice,e,stored,set,$,toast,modal,go,signupDraft}=api;
 const password=(label,name)=>`<div class="field"><label for="d-${name}">${label}</label><div class="d-password-wrap"><input id="d-${name}" name="${name}" type="password" minlength="8" autocomplete="new-password" required placeholder="${name==='confirm'?'Re-enter your password':'Enter a temporary demo password'}"><button type="button" data-d-password="d-${name}" aria-label="Show ${label}">${icon('b25a2.svg')}</button></div></div>`;
 const heading=(title,sub)=>`<div class="d-auth-heading">${logo(true)}<h1>${title}</h1><p>${sub}</p></div>`;
 const social=()=>`<div class="d-auth-divider">Or continue with</div><div class="d-social-login"><button type="button" class="btn outline" data-d-action="social">${icon('eb7ad.svg')}Google</button><button type="button" class="btn outline" data-d-action="social">${icon('d61bf.svg')}Apple</button></div>`;
 const benefits=signup=>`<aside class="d-auth-aside"><h2>${signup?'Why Drive with 365 Trucking?':'Start Earning Today'}</h2><p>${signup?'Join our growing community of professional drivers and enjoy the benefits of working with 365 Trucking.':'Join thousands of drivers delivering with 365 Trucking. Flexible hours, competitive pay, and full support every step of the way.'}</p>${(signup?[['839e4.svg','Earn More','Competitive rates with weekly payouts and performance bonuses'],['946d8.svg','Be Your Own Boss','Choose your own schedule and work as much or as little as you want'],['6f750.svg','Full Protection','Comprehensive insurance coverage and 24/7 driver support'],['36428.svg','Sign-Up Bonus','Get $100 bonus after completing your first 10 deliveries']]:[['839e4.svg','Competitive Earnings','Earn up to $25/hour with bonuses and incentives'],['bee49.svg','Flexible Schedule','Work when you want, as much as you want'],['6f750.svg','Full Support','24/7 driver support and insurance coverage']]).map(x=>`<div class="d-auth-feature">${box(x[0])}<div><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}<p class="d-auth-note" style="color:#fee2e2">Benefits and promotions are design examples, not active offers.</p></aside>`;
 function bindPasswords(){for(const b of root.querySelectorAll('[data-d-password]'))b.onclick=()=>{const input=$('#'+b.dataset.dPassword);input.type=input.type==='password'?'text':'password';b.setAttribute('aria-label',(input.type==='password'?'Show':'Hide')+' password')}}
 if(page==='login'){
   root.innerHTML=`<div class="driver-app"><main class="d-auth"><section class="d-auth-left"><form class="d-auth-form" id="d-login-form">${heading('Welcome Back','Sign in to your 365 Trucking Driver account')}${field('Email Address','email','','email','required placeholder="driver@example.com" autocomplete="email"')}${password('Password','password')}<div class="d-auth-options"><label><input type="checkbox" name="remember">Remember me</label><a href="#/driver/forgot">Forgot Password?</a></div><button class="btn" type="submit">Sign In</button>${social()}<p class="d-auth-bottom">Don't have an account? <a href="#/driver/signup/1">Sign up now</a></p><p class="d-auth-note">Demo sign-in only. Use a temporary password; passwords are not stored. ${link('Explore Driver Demo','dashboard','secondary')}</p><p class="d-auth-bottom"><a href="#/">← Customer Portal</a></p></form></section>${benefits(false)}</main></div>`;
   $('#d-login-form').onsubmit=event=>{event.preventDefault();set('365-driver-profile',{...profile,email:$('#d-email').value});sessionStorage.setItem('365-driver-session','demo');go('dashboard')};bindPasswords();return;
 }
 if(page==='signup'){
  const stepTwo=Number(step)===2;
  root.innerHTML=`<div class="driver-app"><main class="d-auth"><section class="d-auth-left"><form class="d-auth-form" id="d-signup-form">${heading('Join 365 Trucking','Create your driver account and start earning')}<div class="d-signup-steps"><b class="active">1</b><b class="${stepTwo?'active':''}">2</b></div>${stepTwo?`${select('Vehicle Type','vehicle',['Select vehicle type','Cargo Van','Box Truck','Pickup Truck','Car / Sedan','Motorcycle'],signupDraft.vehicle||'Select vehicle type','required')}${field("Driver's License Number",'license',signupDraft.license||'','text','required placeholder="Sample license number"')}<div style="margin-top:24px">${notice('Background Check Required','<p>In the production app, drivers will need to complete a background check and upload vehicle documents before accepting real jobs.</p>','blue','bfdb3.svg')}</div><label class="d-auth-options" style="justify-content:flex-start;gap:10px"><input type="checkbox" required name="terms">I agree to the demo <a href="#/terms">Terms of Service</a> and <a href="#/privacy">Privacy Policy</a></label><div class="d-form-grid">${link('Back','signup/1','outline')}<button class="btn" type="submit">Create Account</button></div>`:`<div class="d-form-grid" style="margin-bottom:24px">${field('First Name','firstName',signupDraft.firstName||'','text','required placeholder="John"')}${field('Last Name','lastName',signupDraft.lastName||'','text','required placeholder="Doe"')}</div>${field('Email Address','email',signupDraft.email||'','email','required placeholder="driver@example.com"')}${field('Phone Number','phone',signupDraft.phone||'','tel','required placeholder="+1 (555) 000-0000"')}${password('Password','password')}<div style="margin-top:24px">${password('Confirm Password','confirm')}</div><button class="btn" type="submit" style="margin-top:24px">Continue to Step 2</button>${social()}`}<p class="d-auth-bottom">Already have an account? <a href="#/driver/login">Sign in</a></p><p class="d-auth-note">Local prototype only. Use sample details. No real account, background check, or verification email is created.</p></form></section>${benefits(true)}</main></div>`;
  $('#d-signup-form').onsubmit=event=>{event.preventDefault();const fd=new FormData(event.currentTarget);if(!stepTwo){if(fd.get('password')!==fd.get('confirm')){toast('Passwords must match.');$('#d-confirm').focus();return}for(const key of ['firstName','lastName','email','phone'])signupDraft[key]=fd.get(key);go('signup/2')}else{if(fd.get('vehicle')==='Select vehicle type'){toast('Choose your vehicle type.');return}Object.assign(signupDraft,{vehicle:fd.get('vehicle'),license:fd.get('license')});set('365-driver-profile',{...profile,...signupDraft});set('365-driver-vehicle',{primary:signupDraft.vehicle});go('welcome')}};bindPasswords();return;
 }
 if(page==='welcome'){
   root.innerHTML=`<div class="driver-app"><main class="d-reset"><section class="d-card d-welcome"><div class="d-success">✓</div><h1>Welcome to 365 Trucking!</h1><p>Your demo driver profile has been created. Let's get you started on your journey to earning.</p><div class="d-welcome-list"><h2>Next Steps to Start Driving</h2><ol>${[['Complete Background Check','In production, complete the required driver verification.'],['Upload Vehicle Documents','Submit your driver license, registration and insurance documents.'],['Complete Driver Training','Learn delivery best practices and app features.'],['Start Accepting Jobs','Once approved, accept delivery jobs and start earning.']].map((x,i)=>`<li><b>${i+1}</b><div><strong>${x[0]}</strong><small>${x[1]}</small></div></li>`).join('')}</ol></div>${notice('Demo Account Created','<p>Your details are saved only in this browser. No verification email was sent.</p>','blue','bfdb3.svg')}<div class="d-form-grid">${link('Upload Documents','documents')}${link('Go to Dashboard','dashboard','outline')}</div><p class="d-auth-bottom">Need help getting started? <a href="#/driver/support">Contact Support</a></p></section></main></div>`;return;
 }
 const sent=page==='reset-sent';
 root.innerHTML=`<div class="driver-app"><main class="d-reset">${heading('Forgot Password?',sent?'Password recovery preview':"No worries, we'll send you reset instructions")}<form class="d-card" id="d-reset-form">${sent?`<div class="d-success" style="width:64px;height:64px">${icon('a30c9.svg')}</div><h2 style="text-align:center">Reset Request Preview</h2><p>In the connected app, reset instructions will be sent to <strong>${e(sessionStorage.getItem('365-reset-email')||'your email')}</strong>.</p>${notice("Didn't receive the email?",'<ul><li>Check your spam or junk folder.</li><li>Make sure you entered the correct email.</li><li>No email was sent by this local demo.</li></ul>','blue','bfdb3.svg')}<button type="submit" class="btn outline">Resend Email</button><p class="d-auth-bottom"><a href="#/driver/forgot">Try a different email</a></p>`:`${field('Email Address','email','','email','required placeholder="driver@example.com"')}<button type="submit" class="btn">Send Reset Link</button>`}</form><a href="#/driver/login" class="d-reset-back">← Back to Sign In</a></main></div>`;
 $('#d-reset-form').onsubmit=event=>{event.preventDefault();if(sent){toast('Demo only: no reset email was sent.');return}sessionStorage.setItem('365-reset-email',$('#d-email').value);go('reset-sent')};
}
